/** P2-016 Internal Beta contracts. Plain JSON only. All business timestamps are Asia/Shanghai local strings. */

export type P2016WebReport = { readonly source_kind: "WEB_REQUEST"; readonly description: string; readonly location: { readonly text: string | null; readonly unknown: boolean } | null; readonly service_code: string | null; readonly impact_scope: "UNKNOWN" | "SELF" | "SINGLE_WORKSTATION" | "MULTIPLE_USERS" | "DEPARTMENT"; readonly reported_department_text: string | null; readonly extension: string | null; readonly supplements: ReadonlyArray<{ readonly input_revision: string; readonly text: string | null }>; };

export type P2016TicketDetail = { readonly id: string; readonly ticket_no: string; readonly request_type: "INCIDENT" | "SERVICE_REQUEST"; readonly status: "NEW" | "QUEUED" | "ACCEPTED" | "IN_PROGRESS" | "WAITING_REQUESTER" | "WAITING_VENDOR" | "RESOLVED" | "CLOSED" | "REOPENED" | "CANCELLED" | "DUPLICATE_LINKED"; readonly priority: "LOW" | "NORMAL" | "HIGH" | "URGENT"; readonly resolver_team_id: string; readonly assignee_id: string | null; readonly version: number; readonly created_at: LocalDateTime; readonly updated_at: LocalDateTime; readonly intake_id: string; readonly external_status: string; readonly allowed_actions: ReadonlyArray<"queue" | "accept" | "start" | "request-information" | "wait-vendor" | "resume" | "resolve" | "confirm" | "reopen" | "cancel" | "add-note" | "unassign" | "assign" | "transfer-assignment" | "takeover" | "takeover-and-start" | "take-and-start" | "accept-for-later" | "take-and-start-with-conversations" | "accept-for-later-with-conversations" | "complete">; readonly handling_cycle?: P2016HandlingCycle | null; readonly web_report?: P2016WebReport; readonly reopen_follow_up?: Readonly<{origin:'WEB_REPORTER'|'BOT_REPORTER'|'STAFF';is_previous_handler:boolean;awaiting_acceptance:true}>; };

export type P2016TicketList = { readonly items: ReadonlyArray<P2016TicketDetail>; readonly next_cursor: string | null; };

export type P2016TicketActionCommand = { readonly client_command_id: string; readonly expected_version: number; readonly reason_code: string; readonly note?: string; readonly external_visible?: boolean; };
/** Dedicated internal-notes HTTP contract. Legacy notes keeps its separate compatibility contract. */
export type P2016InternalNoteCommand = { readonly client_command_id: string; readonly expected_version: number; readonly reason_code: string; readonly note: string; readonly external_visible: false; };
export type P2016InternalNoteResult = { readonly ok: true; readonly ticket_id: string; readonly ticket_version: number; readonly ticket_event_id: string; readonly control_event_id: null; readonly replayed: boolean; };
export type P2016ReopenResult=P2016InternalNoteResult&Readonly<{handling_cycle:Readonly<{id:string;cycle_no:number;first_responsibility_event_id:null;staff_completion_event_id:null}>}>;
export type P2016ReopenReceipt=Readonly<{client_command_id:string;ticket_id:string}>&(Readonly<{state:'UNKNOWN'}>|Readonly<{state:'FAILED';error:Readonly<{code:string;retryable:false}>}>|Readonly<{state:'COMMITTED';result:P2016ReopenResult}>);
export type P2016InternalNoteReceipt = Readonly<{client_command_id:string;ticket_id:string}> & (
  Readonly<{state:'UNKNOWN'}> | Readonly<{state:'COMMITTED';result:P2016InternalNoteResult}> | Readonly<{state:'FAILED';error:Readonly<{code:string;retryable:false}>}>);

export type P2016TicketTransferCommand = { readonly client_command_id: string; readonly expected_version: number; readonly reason_code: string; readonly target_principal_id: string; readonly resolver_team_id?: string; };

export type P2016CombinedTakeoverAccept = { readonly client_command_id: string; readonly ticket_id: string; readonly expected_ticket_version: number; readonly expected_session_row_version: number; readonly reason_code: string; };

export type P2016ResponsibilityView = { readonly ticket_id: string; readonly ticket_assignee_id: string | null; readonly ticket_assignee_name: string | null; readonly resolver_team_id: string; readonly resolver_team_name: string | null; readonly conversations: ReadonlyArray<{ readonly session_id: string; readonly session_row_version: string; readonly combined_accept_allowed: boolean; readonly conversation_principal_id: string | null; readonly conversation_principal_name: string | null; readonly assignment_status: string | null; readonly assignment_version: string | null; }>; };

