export type P2016TemplateCardViewModel = { readonly public_ref: string; readonly suffix: string; readonly status: "NEW" | "QUEUED" | "ACCEPTED" | "IN_PROGRESS" | "WAITING_REQUESTER" | "WAITING_VENDOR" | "RESOLVED" | "CLOSED" | "REOPENED" | "CANCELLED" | "DUPLICATE_LINKED"; readonly occurred_at: LocalDateTime; readonly version: number; readonly notification_type: "TICKET_CREATED" | "TICKET_ACCEPTED" | "TICKET_IN_PROGRESS" | "WAITING_REQUESTER" | "WAITING_VENDOR" | "TICKET_RESOLVED" | "TICKET_CLOSED" | "TICKET_REOPENED" | "TICKET_CANCELLED"; readonly source: "GROUP" | "DIRECT"; };

export type P2016ReporterAccessGrant = { readonly grant_id: string; readonly ticket_id: string; readonly public_ref_id: string; readonly delivery_id: string; readonly message_id: string; readonly reporter_binding_hash: string; readonly nonce: string; readonly token_hash: string; readonly purpose: "REPORTER_TIMELINE"; readonly state: "ISSUED" | "CONSUMED" | "REVOKED" | "EXPIRED"; readonly issued_at: LocalDateTime; readonly issued_epoch_ms: PhysicalEpochMs; readonly expires_at: LocalDateTime; readonly expires_epoch_ms: PhysicalEpochMs; readonly row_version: string; readonly consumed_at: LocalDateTime | null; readonly revoked_at: LocalDateTime | null; readonly consumed_epoch_ms: PhysicalEpochMs | null; readonly revoked_epoch_ms: PhysicalEpochMs | null; };

