export interface UnifiedTicketQueryPort {
  list(input: Readonly<{ authContext: unknown; state?: string; cursor?: string | null; limit?: number }>): Promise<P2016TicketList>;
  detail(input: Readonly<{ authContext: unknown; ticketId: string }>): Promise<P2016TicketDetail>;
  responsibility(input: Readonly<{ authContext: unknown; ticketId: string }>): Promise<P2016ResponsibilityView>;
}

export type P2016CommandResult = Readonly<{ ok: true; ticket_id?: string; ticket_version?: number; ticket_event_id?: string; replayed: boolean }> | Readonly<{ ok: false; error: Readonly<{ code: string; retryable: boolean }>; replayed: boolean }>;
export interface UnifiedTicketCommandPort { perform(input: Readonly<{ authContext: unknown; command: P2016TicketActionCommand & Readonly<{ ticket_id: string; action: string }> }>): Promise<P2016CommandResult>; }
/** Reporter access grants are private persistence metadata; they are NEVER returned by public HTTP reads. */

export type P2016HandlingCycle = {readonly id:string;readonly cycle_no:number;readonly first_responsibility_event_id:string|null;readonly staff_completion_event_id?:string|null};
export type P2016SelfHandlingCommand = {readonly client_command_id:string;readonly expected_version:number;readonly reason_code:string;readonly resolver_team_id:string};
export type P2016SelfHandlingResult = P2016InternalNoteResult & {readonly handling_cycle:P2016HandlingCycle & {readonly first_responsibility_event_id:string}};
export type P2016ConversationHandlingAction='take-and-start-with-conversations'|'accept-for-later-with-conversations';
export type P2016ConversationHandlingCommand=P2016SelfHandlingCommand&{readonly communication_choice:'TAKE_SELECTED'|'RETAIN_CURRENT';readonly sessions:ReadonlyArray<{readonly session_id:string;readonly expected_row_version:number}>};
export type P2016RelatedConversation={readonly session_id:string;readonly session_row_version:string;readonly conversation_principal_id:string|null;readonly conversation_principal_name:string|null;readonly assignment_status:'ASSIGNED'|'UNASSIGNED'|null;readonly take_allowed:boolean};
export type P2016RelatedConversationPage={readonly items:ReadonlyArray<P2016RelatedConversation>;readonly next_cursor:string|null};
export type P2016ConversationHandlingResult=P2016SelfHandlingResult&{readonly communication_choice:'TAKE_SELECTED'|'RETAIN_CURRENT';readonly conversations:ReadonlyArray<{readonly session_id:string;readonly session_row_version:number;readonly control_event_id:string|null;readonly changed:boolean}>};
export type P2016ConversationHandlingAcknowledgement={readonly state:'UNKNOWN'}|{readonly state:'FAILED';readonly error:{readonly code:string;readonly retryable:false}}|{readonly state:'COMMITTED';readonly ticket_id:string;readonly ticket_version:number;readonly ticket_event_id:string};

export type P2016CompletionCommand = Readonly<{client_command_id:string;expected_version:number;reason_code:'STAFF_COMPLETED';handling_cycle_id:string;internal_process:string;external_summary:string;external_summary_confirmed:true}>;
export type P2016CompletionResult = P2016InternalNoteResult & Readonly<{completion:Readonly<{cycle_id:string;cycle_no:number;event_id:string;basis:'STAFF_COMPLETED'}>}>;
export type P2016CompletionReceipt = Readonly<{client_command_id:string;ticket_id:string}> & (Readonly<{state:'UNKNOWN'}>|Readonly<{state:'COMMITTED';result:P2016CompletionResult}>|Readonly<{state:'FAILED';error:Readonly<{code:string;retryable:false}>}>);

export type P2016AssignmentAction='assign'|'transfer-assignment';
/** Receipt acknowledges only the current authorized Ticket; no selected Session identity is returned. */
export type P2016AssignmentAcknowledgement=P2016ConversationHandlingAcknowledgement;
export type P2016AssignmentCommand=Readonly<{client_command_id:string;expected_version:number;reason_code:string;target_principal_id:string;resolver_team_id:string;communication_choice:'TRANSFER_SELECTED'|'RETAIN_CURRENT';sessions:ReadonlyArray<{readonly session_id:string;readonly expected_row_version:number}>}>;
export type P2016AssignmentResult=P2016InternalNoteResult&Readonly<{handling_cycle:P2016HandlingCycle|null;communication_choice:'TRANSFER_SELECTED'|'RETAIN_CURRENT';conversations:ReadonlyArray<{readonly session_id:string;readonly session_row_version:number;readonly control_event_id:string|null;readonly changed:boolean}>}>;
export type P2016AssignmentTargets=Readonly<{resolver_teams:ReadonlyArray<{readonly team_id:string;readonly display_name:string}>;resolver_team_id:string|null;items:ReadonlyArray<{readonly principal_id:string;readonly display_name:string}>}>;
